    "Signed in as {0}, but the server can't be reached right now. It's tried again by itself every few minutes." to Tr(ja = "{0}で ログイン していますが いま サーバーに つながりません。 なんぷんか ごとに じどうで やりなおします。", fr = "Connecté en tant que {0}, mais le serveur est injoignable pour l'instant. Nouvel essai automatique toutes les quelques minutes.", de = "Angemeldet als {0}, aber der Server ist gerade nicht erreichbar. Alle paar Minuten wird es automatisch erneut versucht.", it = "Accesso come {0}, ma il server ora non è raggiungibile. Riprova da solo ogni pochi minuti.", es = "Sesión iniciada como {0}, pero ahora no se puede conectar con el servidor. Se reintenta solo cada pocos minutos.", br = "Conectado como {0}, mas não foi possível acessar o servidor agora. Ele tenta de novo sozinho a cada poucos minutos.", pt = "Sessão iniciada como {0}, mas o servidor não está acessível de momento. Volta a tentar sozinho a cada poucos minutos."),
